style.content:
body {
    margin: 0;
    font-family: 'Poppins', sans-serif;
    background-color: #f0fdf4;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    overflow: hidden;
}

.game-container {
    text-align: center;
    width: 95%;
    max-width: 800px;
}

.header {
    background: white;
    padding: 19px;
    border-radius: 20px;
    box-shadow: 0 10px 25px rgba(0,0,0,0.05);
    margin-bottom: 16px;
}

.score-board {
    font-size: 28px;
    font-weight: bold;
    color: #16a34a;
}

#game-area {
    width: 100%;
    height: 450px;
    background: #ffffff;
    border-radius: 25px;
    position: relative;
    border: 4px solid #bbf7d0;
    box-shadow: inset 0 0 20px rgba(0,0,0,0.02);
    cursor: pointer;
}

/* Gaya Asas Item */
.item {
    position: absolute;
    padding: 12px 18px;
    border-radius: 50px;
    font-weight: bold;
    color: white;
    user-select: none;
    cursor: pointer;
    transition: transform 0.1s ease;
    display: flex;
    align-items: center;
    gap: 5px;
}

.item:active { transform: scale(0.8); }

/* Warna Mengikut Kategori */
.zikir { background: #4caf50; border: 2px solid #2e7d32; }

.solat { background: #1b5e20; border: 2px solid #ffd700; }

.rare { 
    background: linear-gradient(135deg, #8b5cf6, #d946ef); 
    border: 2px solid #fff;
    box-shadow: 0 0 15px rgba(217, 70, 239, 0.5);
    animation: pulse 1.5s infinite;
}

@keyframes pulse {
    0% { transform: scale(1); }
    50% { transform: scale(1.1); }
    100% { transform: scale(1); }
}

.legend {
    margin-top: 15px;
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
}

.tag {
    padding: 5px 10px;
    border-radius: 20px;
    font-size: 14px;
    color: white;
}

script.content:
const gameArea = document.getElementById('game-area');
const scoreDisplay = document.getElementById('score');
const resetBtn = document.getElementById('reset-btn');

// Load skor dari LocalStorage
let score = parseInt(localStorage.getItem('totalPahala')) || 0;
scoreDisplay.innerText = score;

// Senarai Item Ibadah
const daftarPahala = [
    { nama: "Alhamdulillah", tipe: "zikir", poin: 10 },
    { nama: "Subhanallah", tipe: "zikir", poin: 10 },
    { nama: "Allahu Akbar", tipe: "zikir", poin: 10 },
    { nama: "Astaghfirullah", tipe: "zikir", poin: 10 },
    { nama: "Solat Fardhu", tipe: "solat", poin: 100 },
    { nama: "Solat Sunat", tipe: "solat", poin: 50 },
    { nama: "Solat Berjamaah", tipe: "solat", poin: 120 },
    { nama: "Baca Al-Quran", tipe: "rare", poin: 200 },
    { nama: "Puasa Sunnah", tipe: "rare", poin: 300 },
    { nama: "Zakat & Sedekah", tipe: "rare", poin: 400 }
];

function spawnItem() {
    const data = daftarPahala[Math.floor(Math.random() * daftarPahala.length)];
    
    const item = document.createElement('div');
    item.className = `item ${data.tipe}`;
    item.innerHTML = `<span>${data.nama}</span>`;

    // Posisi rawak
    const maxX = gameArea.clientWidth - 150;
    const maxY = gameArea.clientHeight - 60;
    item.style.left = Math.random() * maxX + "px";
    item.style.top = Math.random() * maxY + "px";

    // Klik untuk dapat pahala
    item.onclick = () => {
        score += data.poin;
        scoreDisplay.innerText = score;
        localStorage.setItem('totalPahala', score);
        
        // Kesan visual ringkas semasa klik
        item.style.transform = "scale(1.5)";
        item.style.opacity = "0";
        setTimeout(() => item.remove(), 100);
    };

    gameArea.appendChild(item);

    // Item hilang sendiri jika tidak diklik dalam 2.5 saat
    setTimeout(() => {
        if (item.parentElement) item.remove();
    }, 5900);
}

setInterval(spawnItem, 2000);
